 await check('High-line paste and API regrowth never assign the entire large text to the native control',async()=>{const insert=('paste\n').repeat(11000);for(const api of [false,true]){await page.evaluate(({insert,api})=>{nimloEditor.value=('x\n').repeat(11000);nimloEditor.value='seed';nimloEditor.setSelectionRange(4,4);const input=nimloEditor.input,descriptor=Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value');window.__nativeAssignedLines=0;Object.defineProperty(input,'value',{configurable:true,get(){return descriptor.get.call(this);},set(value){window.__nativeAssignedLines=Math.max(window.__nativeAssignedLines,String(value).split('\n').length);descriptor.set.call(this,value);}});try{if(api)nimloEditor.setRangeText(insert,4,4,'end');else{const data=new DataTransfer();data.setData('text/plain',insert);input.dispatchEvent(new ClipboardEvent('paste',{clipboardData:data,bubbles:true,cancelable:true}));}}finally{delete input.value;}},{insert,api});assert.equal(await page.evaluate(()=>nimloEditor.large),true);await expectText('seed'+insert);assert.equal(await page.evaluate(()=>nimloEditor.selectionStart),4+insert.length);assert((await page.evaluate(()=>window.__nativeAssignedLines))<=161);}});
