   await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
   assert.equal(await page.inputValue('#code-input'),before.value);assert.equal(await page.evaluate(()=>nimloEditor.start),before.start);assert.equal(await page.evaluate(()=>window.__bufferAssignments),0);
