  const startX=geometry.left+4.25*geometry.char,startY=geometry.top+geometry.padding+20.5*geometry.height,edgeY=geometry.bottom-5,returnX=geometry.left+7.25*geometry.char,returnY=geometry.top+geometry.padding+8.5*geometry.height;
