   await page.evaluate(()=>new Promise(resolve=>requestAnimationFrame(()=>requestAnimationFrame(resolve))));
   const returned=await page.evaluate(({x,y,stride})=>{const m=nimloEditor.metrics(),r=nimloEditor.scroller.getBoundingClientRect(),line=Math.floor((y-r.top+nimloEditor.scrollTop-m.padding)/m.height),column=Math.round((x-r.left+nimloEditor.scrollLeft)/m.char);return {expected:line*stride+column,range:nimloEditor.getSelection(),scrollTop:nimloEditor.scrollTop};},{x:returnX,y:returnY,stride});
